def sanitize_to_float(text):
    digits = ''.join(char for char in text if char.isdigit() or char == '.')
    if not digits:
        return 0.0
    dot_count = digits.count('.')
    if dot_count == 0:
        return float(digits)
    if dot_count > 1:
        first_dot = digits.find('.')
        last_dot = digits.rfind('.')
        digits = digits[:first_dot] + digits[first_dot + 1:]
        if digits.find('.') == -1:
            return float(digits)
    try:
        return float(digits)
    except ValueError:
        return 0.0

