    example_a = "test123abc45"
    example_b = "xyz"
    example_c = "007"
    output_a = build_digit_string(example_a)
    print(output_a)
    try:
        output_b = build_digit_string(example_b)
        print(output_b)
    except EmptyDigitResultException as err:
        print(str(err))
    output_c = build_digit_string(example_c)
    print(output_c)

