    case_a = "alpha-9-beta-88"
    case_b = "pure-letters-only"
    case_c = "42"

    test_cases = [case_a, case_b, case_c]

    for item in test_cases:
        try:
            output = extract_and_concatenate_numeric(item)
            print(output)
        except MissingNumericCharacters as err:
            print(err)

