class NoDigitsError(Exception):
    def __init__(self, message="No digits found in the input string"):
        self.message = message
        super().__init__(self.message)

def extract_digits(s):
    digits = [char for char in s if char.isdigit()]
    if not digits:
        raise NoDigitsError()
    return ''.join(digits)

