import re

def extract_numeric_substrings(text):
    pattern = r'-?\b\d+\.?\d*\b|-\d+\.\d+|\b\d+\b'
    matches = re.findall(r'-?\d+\.?\d*', text)
    result = []
    for match in matches:
        try:
            if '.' in match:
                result.append(float(match))
            else:
                result.append(float(match))
        except ValueError:
            continue
    return result

