import re

def extract_floats(text):
    pattern = r'-?\d+\.?\d*'
    matches = re.findall(pattern, text)
    result = []
    for match in matches:
        if match.strip().count('.') > 1:
            continue
        try:
            val = float(match)
            result.append(val)
        except ValueError:
            continue
    return result

