    test_cases = [
        "user@example.com",
        "invalid.email@",
        "user@.com",
        "..user@example.com",
        "user.name+tag@sub.domain.co.uk",
        "a-b@c-d.org"
    ]
    for test in test_cases:
        result = validate_email_address(test)
        print(result)

