def validate_email(email: str) -> bool:
    if not isinstance(email, str):
        return False
    if len(email) > 254:
        return False
    if '@' not in email:
        return False
    if email.startswith('.') or email.endswith('.'):
        return False
    if '..' in email:
        return False
    if email.count('@') != 1:
        return False
    if email.startswith('-') or email.endswith('-'):
        return False
    if email.startswith('.') or email.endswith('.'):
        return False
    if not _email_pattern.match(email):
        return False
    local, domain = email.rsplit('@', 1)
    if len(local) > 64:
        return False
    if domain.startswith('-') or domain.endswith('-'):
        return False
    return True

