def check_palindrome(text):
    filtered = []
    for char in text:
        if char.isalnum():
            filtered.append(char.lower())
    left = 0
    right = len(filtered) - 1
    while left < right:
        if filtered[left] != filtered[right]:
            return False
        left += 1
        right -= 1
    return True

