class PalindromeChecker:
    def __init__(self, text):
        self.text = text

    def normalize(self):
        result = []
        for char in self.text:
            if char.isalnum():
                result.append(char.lower())
        return "".join(result)

    def check(self):
        normalized = self.normalize()
        length = len(normalized)
        mid = length // 2
        for i in range(mid):
            if normalized[i] != normalized[length - 1 - i]:
                return False
        return True

