def validate_email_syntax(email):
    if not isinstance(email, str) or len(email) == 0:
        return False
    at_count = 0
    for i, char in enumerate(email):
        if char == '@':
            at_count += 1
            if at_count > 1:
                return False
            local_part = email[:i]
            domain_part = email[i+1:]
            break
    if at_count != 1:
        return False
    if not local_part or not domain_part:
        return False
    if not all(c.isalnum() or c in '._%+-' for c in local_part):
        return False
    if local_part.startswith('.') or local_part.endswith('.'):
        return False
    if '..' in local_part:
        return False
    if not domain_part or domain_part.startswith('.') or domain_part.endswith('.'):
        return False
    domain_labels = domain_part.split('.')
    if len(domain_labels) < 2:
        return False
    for label in domain_labels:
        if not label:
            return False
        if not all(c.isalnum() or c == '-' for c in label):
            return False
        if label.startswith('-') or label.endswith('-'):
            return False
    return True

if __name__ == '__main__':
    print(validate_email_syntax('test@example.com'))
    print(validate_email_syntax('invalid.email@'))
    print(validate_email_syntax('@domain.com'))
    print(validate_email_syntax('user.name+tag@domain.co.uk'))
    print(validate_email_syntax('bad..dot@domain.com'))
    print(validate_email_syntax('no-at-sign.com'))
    print(validate_email_syntax(''))
    print(validate_email_syntax('valid@sub.domain.org'))

import re
import string

def validate_email(email: str) -> bool:
    if not isinstance(email, str):
        return False

    length = len(email)
    if length < 3 or length > 254:
        return False

    if email[0] == '.' or email[-1] == '.':
        return False

    if '..' in email:
        return False

    at_index = email.rfind('@')
    if at_index == -1:
        return False

    local_part = email[:at_index]
    domain_part = email[at_index + 1:]

    if not local_part or not domain_part:
        return False

    if len(local_part) > 64:
        return False

    allowed_special_chars = "!#$%&'*+/=?^_`{|}~.-"
    for char in local_part:
        if char.isalnum() or char in allowed_special_chars:
            continue
        if char == '.':
            prev_idx = local_part.index(char)
            if prev_idx == 0 or local_part[prev_idx - 1] != '.':
                continue
        return False

    domain_labels = domain_part.split('.')
    if len(domain_labels) < 2:
        return False

    for label in domain_labels:
        if not label:
            return False
        if len(label) > 63:
            return False
        if label[0] == '-' or label[-1] == '-':
            return False
        for char in label:
            if not (char.isalnum() or char == '-'):
                return False

    try:
        domain_part.encode('ascii')
        local_part.encode('ascii')
    except UnicodeEncodeError:
        return False

    if domain_part.count('.') == 0:
        return False

    pattern = r'^(?!\.)((?:[a-zA-Z0-9!#$%&\'*+/=?^_`{|}~-]+(?:\.[a-zA-Z0-9!#$%&\'*+/=?^_`{|}~-]+)*|"((?:[ \t]|[^"\\])|\\.)*")\.)+(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?|[\u0080-\uFFFF])$'

    return bool(re.match(pattern, email, re.IGNORECASE))

