        "user@sub.domain.com",
        "user+tag@example.co.uk",
        "very.cause@example",
        "name with space@example.com",
        "user@[192.168.1.1]"
    ]
    for email_addr in test_cases:
        result = is_valid_email(email_addr)
        print(f"{email_addr}: {result}")

import re

def validate_email(email: str) -> bool:
    if not isinstance(email, str):
        return False

    if len(email) > 254:
        return False

    at_count = email.count('@')
    if at_count != 1:
        return False

    local_part, domain_part = email.split('@')

    if len(local_part) == 0 or len(local_part) > 64:
        return False

    if len(domain_part) == 0:
        return False

    if domain_part[0] == '.' or domain_part[-1] == '.':
        return False

    if '..' in domain_part:
        return False

    domain_labels = domain_part.split('.')
    for label in domain_labels:
        if len(label) == 0:
            return False
        if len(label) > 63:
            return False
        if label[0] == '-' or label[-1] == '-':
            return False

    local_pattern = r"^[a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+)*$"
    domain_label_pattern = r"^[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?$"

    if not re.match(local_pattern, local_part):
        return False

    for label in domain_labels:
        if not re.match(domain_label_pattern, label):
            return False

    if len(domain_labels) < 2:
        return False

    tld = domain_labels[-1]
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9]*$', tld):
        return False
    if len(tld) < 2:
        return False

    return True

